mapper.select:
SELECT

FROM
iot_device
WHERE
del_flag = '0'

    AND device_code LIKE CONCAT('%', #{device.deviceCode}, '%')


    AND device_name LIKE CONCAT('%', #{device.deviceName}, '%')


    AND product_id = #{device.productId}


    AND product_code = #{device.productCode}


    AND status = #{device.status}


    AND region = #{device.region}


    AND factory_code = #{device.factoryCode}

ORDER BY create_time DESC
